/**
 * LLM-as-judge for the app evals.
 *
 * The faithfulness and helpfulness rubrics are imported from `evals/judge.ts`
 * unchanged, so a score here means the same thing as a score from
 * `bun run eval:judge` and from the two Arize template evaluators it mirrors
 * (faithfulness-to-draft, feedback-helpfulness). The rubrics that only make
 * sense with the app's corpus (planted weaknesses, rewrite improvement) are
 * defined below.
 *
 * Judges are optional. `--judge none` scores with the deterministic checks
 * alone, which is what CI and the mock model use.
 */
import { createEvalClient } from "../llm-client";
import {
  CHOICES,
  FAITHFULNESS_TEMPLATE,
  HELPFULNESS_TEMPLATE,
  judgeSystemPrompt,
  parseVerdict,
  type Verdict,
} from "../judge";
import type { Score } from "./scoring";

export type JudgeMode = "none" | "notorganic" | "openai-compatible";

export interface Judge {
  label: string;
  complete(system: string, user: string, signal: AbortSignal): Promise<string>;
}

type Env = Readonly<Record<string, string | undefined>>;

export function createJudge(mode: JudgeMode, env: Env): Judge | null {
  if (mode === "none") return null;
  if (mode === "notorganic") {
    const complete = createEvalClient(env);
    const model = env.JUDGE_MODEL ?? "reasoning";
    return {
      label: `notorganic:${model}`,
      complete: (system, user, signal) =>
        complete(
          {
            model,
            temperature: 0,
            // Same headroom as the app (NO_OUTPUT_CEILING in convex/agents.ts):
            // the gateway's default lets a reasoning model think past it.
            max_tokens: 16_000,
            messages: [
              { role: "system", content: system },
              { role: "user", content: user },
            ],
          },
          signal,
        ),
    };
  }
  const baseUrl = env.TWYNE_JUDGE_BASE_URL?.trim().replace(/\/+$/, "");
  const model = env.TWYNE_JUDGE_MODEL?.trim();
  if (!baseUrl || !model)
    throw new Error(
      "TWYNE_JUDGE_BASE_URL and TWYNE_JUDGE_MODEL are required for --judge openai-compatible",
    );
  return {
    label: `openai-compatible:${model}`,
    async complete(system, user, signal) {
      const response = await fetch(`${baseUrl}/chat/completions`, {
        method: "POST",
        headers: {
          "content-type": "application/json",
          ...(env.TWYNE_JUDGE_API_KEY
            ? { authorization: `Bearer ${env.TWYNE_JUDGE_API_KEY}` }
            : {}),
        },
        body: JSON.stringify({
          model,
          temperature: 0,
          messages: [
            { role: "system", content: system },
            { role: "user", content: user },
          ],
        }),
        signal,
      });
      if (!response.ok) {
        await response.body?.cancel();
        throw new Error(`Judge request failed (${response.status})`);
      }
      const json = (await response.json()) as {
        choices?: Array<{ message?: { content?: unknown } }>;
      };
      const content = json.choices?.[0]?.message?.content;
      if (typeof content !== "string")
        throw new Error("Judge response missing content");
      return content;
    },
  };
}

async function labelled(
  judge: Judge,
  prompt: string,
  valid: Record<string, number>,
): Promise<Verdict> {
  const raw = await judge.complete(
    judgeSystemPrompt(Object.keys(valid)),
    prompt,
    AbortSignal.timeout(120_000),
  );
  return parseVerdict(raw, valid);
}

export function judgeFaithfulness(
  judge: Judge,
  draft: string,
  output: string,
): Promise<Verdict> {
  return labelled(judge, FAITHFULNESS_TEMPLATE(draft, output), CHOICES.faithfulness);
}

export function judgeHelpfulness(
  judge: Judge,
  persona: string,
  draft: string,
  output: string,
): Promise<Verdict> {
  return labelled(
    judge,
    HELPFULNESS_TEMPLATE(persona, draft, output),
    CHOICES.helpfulness,
  );
}

/**
 * A graded read of one editor's note: the faithfulness and helpfulness
 * rubrics above pass nearly every competent note (1.00 and 0.98 on the first
 * Not Organic run), so they cannot rank one room against another. This asks
 * how much the note is worth to the writer, on anchored levels, and states
 * the expected distribution so "competent" lands in the middle.
 */
export async function judgeNoteValue(
  judge: Judge,
  input: { draft: string; persona: string; note: string; anchor?: string },
): Promise<{ score: number | null; label: string; explanation: string }> {
  const raw = await judge.complete(
    `You are a demanding senior editor grading another editor's note. Respond with a JSON object exactly: ` +
      `{"level": <integer 1-5>, "explanation": "<one sentence naming what the note gets right or wrong>"}. No other text.`,
    `Grade how much this note is worth to the writer of this draft.\n\n` +
      `1 = generic, wrong about the draft, or misreads the passage it quotes.\n` +
      `2 = about this draft but obvious or surface-level: restates the passage, praises or objects without a reason, or offers no usable next move.\n` +
      `3 = specific and correct, with a usable next move; what a competent editor writes.\n` +
      `4 = specific and correct, and names a non-obvious problem or strength with a concrete move that would change the next draft.\n` +
      `5 = the observation a top editor would lead with for this piece; it reframes the draft's main problem or protects its best move.\n\n` +
      `Most competent notes are a 3. Give 4 or 5 only when the note says something a careful writer would likely not have seen themselves. ` +
      `Check the note against the passage it quotes: a note that misdescribes it cannot score above 2.\n\n` +
      `Editor: ${input.persona}\n` +
      (input.anchor ? `Passage the note quotes:\n"${input.anchor}"\n\n` : "") +
      `Note:\n${input.note}\n\nDraft:\n${input.draft}`,
    AbortSignal.timeout(120_000),
  );
  const json = raw.match(/\{[\s\S]*\}/)?.[0] ?? "{}";
  try {
    const parsed = JSON.parse(json) as { level?: unknown; explanation?: unknown };
    const level = Number(parsed.level);
    if (!Number.isInteger(level) || level < 1 || level > 5) throw new Error("level");
    return {
      score: (level - 1) / 4,
      label: `level ${level}`,
      explanation: typeof parsed.explanation === "string" ? parsed.explanation : "",
    };
  } catch {
    return { score: null, label: "judge-error", explanation: raw.slice(0, 200) };
  }
}

/** Longer label first: the fallback parser matches by substring. */
const IMPROVEMENT = { not_improved: 0, improved: 1 };

export function judgeRewrite(
  judge: Judge,
  input: { draft: string; original: string; problem: string; replacement: string },
): Promise<Verdict> {
  return labelled(
    judge,
    `An editor was asked to rewrite one passage of a draft.\n\n` +
      `Draft (context only):\n${input.draft}\n\n` +
      `Original passage:\n${input.original}\n\n` +
      `What was wrong with it:\n${input.problem}\n\n` +
      `Proposed replacement:\n${input.replacement}\n\n` +
      `Answer "improved" if the replacement fixes the stated problem, keeps the ` +
      `passage's meaning and facts, and would read naturally in the draft. ` +
      `Answer "not_improved" if it misses the problem, changes the meaning, ` +
      `drops facts, or reads worse.`,
    IMPROVEMENT,
  );
}

/**
 * How many planted weaknesses the rubric's feedback names. Returns the share
 * found, with the judge's list as the explanation and one item per weakness
 * (`w1`, `w2`, ...) so Jev's reading of the same weaknesses can be joined.
 * A reply with no readable list is a judge failure, not a recall of zero.
 */
export async function judgeWeaknessRecall(
  judge: Judge,
  input: { draft: string; weaknesses: string[]; feedback: string },
): Promise<Score> {
  const numbered = input.weaknesses.map((w, i) => `${i + 1}. ${w}`).join("\n");
  const raw = await judge.complete(
    `You are a strict evaluator. Respond with a JSON object exactly: ` +
      `{"identified": [<numbers of the weaknesses the feedback identifies>], "explanation": "<one sentence>"}. No other text.`,
    `A draft was written with known weaknesses. Decide which of them the ` +
      `reviewers' feedback identifies, in substance and about this draft. ` +
      `General advice that happens to fit does not count.\n\n` +
      `Draft:\n${input.draft}\n\nKnown weaknesses:\n${numbered}\n\n` +
      `Reviewers' feedback:\n${input.feedback}`,
    AbortSignal.timeout(120_000),
  );
  const json = raw.match(/\{[\s\S]*\}/)?.[0] ?? "{}";
  let identified: number[] = [];
  let explanation = "";
  try {
    const parsed = JSON.parse(json) as {
      identified?: unknown;
      explanation?: unknown;
    };
    if (!Array.isArray(parsed.identified)) throw new Error("no list");
    identified = parsed.identified
      .map(Number)
      .filter((n) => Number.isInteger(n) && n >= 1 && n <= input.weaknesses.length);
    explanation = typeof parsed.explanation === "string" ? parsed.explanation : "";
  } catch {
    return { score: null, label: "judge-error", explanation: raw.slice(0, 200) };
  }
  const found = new Set(identified);
  return {
    score: input.weaknesses.length ? found.size / input.weaknesses.length : 0,
    explanation:
      `${found.size}/${input.weaknesses.length} identified` +
      (explanation ? `: ${explanation}` : ""),
    items: Object.fromEntries(input.weaknesses.map((_, i) => [`w${i + 1}`, found.has(i + 1) ? 1 : 0])),
  };
}

/**
 * Run one judged metric. A judge that fails marks that metric "judge-error"
 * instead of failing the case: the app's answer is still worth scoring.
 */
export async function judged(task: () => Promise<Score>): Promise<Score> {
  try {
    return await task();
  } catch (error) {
    return {
      score: null,
      label: "judge-error",
      explanation: error instanceof Error ? error.message : String(error),
    };
  }
}

/* ── Jev (System One) as an evaluator ─────────────────────────────── */

/**
 * Jev answers typed questions with calibrated probabilities instead of
 * writing a verdict. It goes through the app's own System One path
 * (`LocalApp.judge`), so an eval asks it exactly as the editors' review gate
 * does: same transport, metering and limits.
 *
 * Each case batches its questions into one request; they run in parallel and
 * cannot see one another. A Score's expected value is scaled to 0..1 by its
 * top level; a Noul is already a probability.
 */
export type JevAsk = (request: {
  state: Record<string, string>;
  questions: Record<
    string,
    { type: "noul" | "choice" | "score"; instructions: string; criteria?: string[] }
  >;
}) => Promise<{ ok: boolean; answers?: Record<string, unknown>; error?: string }>;

export interface JevVerdict {
  score: number | null;
  /** How concentrated Jev's distribution was (Score/Choice), or the Noul. */
  confidence: number | null;
  label?: string;
}

export function readJevAnswer(answer: unknown): JevVerdict {
  const a = (answer ?? {}) as {
    type?: string;
    noul?: number;
    score?: number;
    confidence?: number;
    legend?: Record<string, string>;
    choice?: string;
  };
  if (a.type === "noul" && typeof a.noul === "number")
    return { score: a.noul, confidence: null, label: a.noul >= 0.5 ? "yes" : "no" };
  if (a.type === "score" && typeof a.score === "number") {
    const top = Math.max(1, Object.keys(a.legend ?? { 0: "", 1: "" }).length - 1);
    return {
      score: a.score / top,
      confidence: typeof a.confidence === "number" ? a.confidence : null,
      label: `level ${a.score.toFixed(1)}`,
    };
  }
  if (a.type === "choice" && typeof a.choice === "string")
    return {
      score: null,
      confidence: typeof a.confidence === "number" ? a.confidence : null,
      label: a.choice,
    };
  return { score: null, confidence: null };
}

/** Clairic typed extraction through the app's own path (`LocalApp.extract`). */
export type ClairicAsk = (request: {
  state?: string;
  fields: Record<string, { type: string; instructions?: string; [key: string]: unknown }>;
  reference_date?: string;
}) => Promise<{ ok: boolean; answers?: Record<string, unknown>; error?: string }>;

/** Run one batched Jev request; a failure marks every question jev-error. */
export async function askJev(
  jev: JevAsk,
  state: Record<string, string>,
  questions: Parameters<JevAsk>[0]["questions"],
): Promise<Record<string, Score>> {
  const ids = Object.keys(questions);
  try {
    const result = await jev({ state, questions });
    if (!result.ok || !result.answers)
      return Object.fromEntries(
        ids.map((id) => [id, { score: null, label: "jev-error", explanation: result.error ?? "no answer" }]),
      );
    return Object.fromEntries(
      ids.map((id) => {
        const v = readJevAnswer(result.answers?.[id]);
        return [
          id,
          {
            score: v.score,
            label: v.label ?? "jev-error",
            explanation:
              v.confidence !== null ? `Jev confidence ${v.confidence.toFixed(2)}` : "",
          },
        ];
      }),
    );
  } catch (error) {
    return Object.fromEntries(
      ids.map((id) => [
        id,
        { score: null, label: "jev-error", explanation: error instanceof Error ? error.message : String(error) },
      ]),
    );
  }
}

/**
 * Jev's read of one editor's note, on the same ladder `judgeNoteValue` uses,
 * so the two evaluators can be compared note for note. Levels describe
 * situations, low to high, each standing on its own.
 */
export const JEV_NOTE_QUESTIONS = {
  jev_note_value: {
    type: "score" as const,
    instructions:
      "How much is `note` worth to the writer of `draft`? `note` is one editor's comment and `anchor` is the passage it quotes.",
    criteria: [
      "The note is generic advice that could apply to any draft, or it misreads or misdescribes the passage it quotes.",
      "The note is about this draft but obvious: it restates the passage, or praises or objects without saying why, and gives no usable next step.",
      "The note is specific and correct about this draft and gives the writer a usable next step, as a competent editor would.",
      "The note names a non-obvious problem or strength in this draft, with a concrete step that would change the next version.",
      "The note is the observation a top editor would lead with for this piece: it reframes the draft's main problem or protects its best move.",
    ],
  },
  jev_grounded: {
    type: "noul" as const,
    instructions:
      "Does `note` make a claim about specific content, wording or argument that appears in `draft`, rather than general writing advice?",
  },
};

/* ── Reading several Jev answers as one metric ───────────────────── */

type JevQuestions = Parameters<JevAsk>[0]["questions"];

/**
 * The mean of several Noul answers, kept per item. With calibrated
 * probabilities the mean is the expected share of items that hold, so a
 * metric built this way reads like its deterministic counterpart (a share of
 * weaknesses named, facts kept, drifts found). `empty` is the score when there
 * are no items, following the suites' "nothing to find" convention.
 */
export function jevShare(
  answers: Record<string, Score>,
  ids: Record<string, string>,
  options: { empty?: number; emptyLabel?: string; invert?: boolean } = {},
): Score {
  const keys = Object.keys(ids);
  if (!keys.length)
    return { score: options.empty ?? 1, label: options.emptyLabel ?? "nothing to check", items: {} };
  const items: Record<string, number> = {};
  for (const item of keys) {
    const value = answers[ids[item]]?.score;
    if (typeof value === "number") items[item] = options.invert ? 1 - value : value;
  }
  const values = Object.values(items);
  if (!values.length)
    return {
      score: null,
      label: "jev-error",
      explanation: answers[ids[keys[0]]]?.explanation ?? "no answer",
    };
  const score = values.reduce((sum, v) => sum + v, 0) / values.length;
  const likely = values.filter((v) => v >= 0.5).length;
  return {
    score,
    label: `jev ${likely} of ${values.length}`,
    explanation: Object.entries(items)
      .map(([item, p]) => `${item} ${p.toFixed(2)}`)
      .join(", "),
    items,
  };
}

/**
 * A weighted mean of Jev readings, each already on 0..1: the composite
 * scoring pattern, with the weights in code where they can be argued with.
 * Null when any part is missing, so a composite never silently drops a part.
 */
export function jevComposite(parts: Array<[Score | undefined, number]>): Score {
  if (parts.some(([s]) => typeof s?.score !== "number"))
    return { score: null, label: "jev-error", explanation: "a part of the composite is missing" };
  const total = parts.reduce((sum, [, w]) => sum + w, 0);
  const score = parts.reduce((sum, [s, w]) => sum + (s!.score as number) * w, 0) / total;
  return {
    score,
    label: `jev ${score >= 0.5 ? "pass" : "fail"}`,
    explanation: `weighted mean of ${parts.length} Jev readings`,
  };
}

/** Invert a Noul: the probability that something did not happen. */
export function jevNot(answer: Score | undefined, yes: string, no: string): Score {
  if (typeof answer?.score !== "number")
    return { score: null, label: "jev-error", explanation: answer?.explanation ?? "no answer" };
  const p = 1 - answer.score;
  return { score: p, label: p >= 0.5 ? yes : no, explanation: `P = ${p.toFixed(2)}` };
}

/* ── Rubric: the four dimensions, read blind ─────────────────────── */

/**
 * Jev's reading of the rubric's four dimensions. The levels follow the
 * anchors the app's own judges are given (prompts/*-judge-user.md at 1, 4,
 * 7 and 10), so level k scaled to 0..1 lines up with an app score of
 * 1 + 9k/3 and the two can be compared directly. The state holds the draft
 * and the commission only: never the app's grades or rationales, which would
 * make agreement circular.
 */
export const JEV_RUBRIC_QUESTIONS = {
  jev_sufficiency: {
    type: "score" as const,
    instructions:
      "How fully does `draft` develop…4751 tokens truncated…ch((v, i) => totals.set(clusters[i], (totals.get(clusters[i]) ?? 0) + (v - m)));
  const g = totals.size;
  if (g < 2) return { se: null, clusters: g };
  let squares = 0;
  for (const total of totals.values()) squares += total * total;
  return { se: Math.sqrt((g / (g - 1)) * squares) / n, clusters: g };
}

/**
 * Mean, spread and 95% interval of one metric over the cases that have it.
 *
 * Every score lives on 0..1 and many sit near an end (nine notes of ten
 * rated good), where a t interval on a handful of cases is far too narrow.
 * So the interval is Wilson's, on an effective sample size: the number of
 * pass/fail trials with the same variance of the mean, p(1 − p) / se², with
 * se cluster-robust (Korn and Graubard's interval for clustered proportions).
 * When the variance is estimated rather than implied by the mean, the
 * critical value is t on clusters − 1 degrees of freedom. Independent
 * pass/fail cases get the plain Wilson interval. When every value is the
 * same there is no design effect to estimate and each point counts once.
 */
export function summarizeValues(
  points: Array<{ value: number | null | undefined; cluster: string }>,
): MetricSummary {
  const present = points.filter(
    (p): p is { value: number; cluster: string } =>
      typeof p.value === "number" && Number.isFinite(p.value),
  );
  const n = present.length;
  if (n === 0)
    return { mean: null, n: 0, ci: null, se: null, sd: null, clusters: 0, effectiveN: null, method: null };
  const values = present.map((p) => p.value);
  const mean = average(values);
  const sd = sampleSd(values);
  const { se, clusters } = clusterSe(
    values,
    present.map((p) => p.cluster),
  );
  if (clusters < 2 || se === null)
    return { mean, n, ci: null, se: null, sd, clusters, effectiveN: null, method: null };

  const p = clamp01(mean);
  const binary = values.every((v) => v === 0 || v === 1);
  // No variation, no design effect to estimate: count every case, as Korn
  // and Graubard do. Scores copied across a cluster are collapsed before this.
  if (se === 0 || p * (1 - p) === 0)
    return { mean, n, ci: wilson(p, n), se, sd, clusters, effectiveN: n, method: "wilson" };
  if (binary && clusters === n)
    return { mean, n, ci: wilson(p, n), se, sd, clusters, effectiveN: n, method: "wilson" };
  const effectiveN = (p * (1 - p)) / (se * se);
  return {
    mean,
    n,
    ci: wilson(p, effectiveN, tCritical(clusters - 1)),
    se,
    sd,
    clusters,
    effectiveN,
    method: "wilson-t",
  };
}

/* ── Clusters and facets ─────────────────────────────────────────── */

/**
 * The cluster a case belongs to. Reports written since clusters were
 * recorded carry it; older ones are read from the case_id conventions:
 * research cases are `<draft>:<claim or strategy>`, rubric cases end in
 * `-strong` or `-weak`.
 */
export function clusterOf(suite: string, c: CaseLike): string {
  if (c.cluster) return c.cluster;
  if (suite.startsWith("research") && c.case_id.includes(":"))
    return c.case_id.slice(0, c.case_id.indexOf(":"));
  if (suite === "rubric") return c.case_id.replace(/-(strong|weak)$/, "");
  return c.case_id;
}

/** A case attribute, with the same fallback for reports that predate facets. */
export function facetOf(suite: string, c: CaseLike, name: string): string | undefined {
  const recorded = c.facets?.[name];
  if (recorded !== undefined) return recorded;
  if (suite === "rubric" && name === "quality")
    return c.case_id.match(/-(strong|weak)$/)?.[1];
  if (suite === "research-targets" && name === "strategy")
    return c.case_id.match(/:(hosted|model)$/)?.[1];
  return undefined;
}

function scored(c: CaseLike): boolean {
  return !c.skipped;
}

/**
 * Is this metric copied across each cluster rather than measured per case?
 * Older rubric reports did not mark their pair orderings, so those are
 * recognised by name.
 */
export function sharedMetric(suite: string, name: string, cases: CaseLike[]): boolean {
  return (
    cases.some((c) => c.scores[name]?.sharedByCluster) ||
    (suite === "rubric" && /_order$/.test(name))
  );
}

/** Every metric in a suite's cases, with a cluster-aware interval. */
export function summarizeCases(
  suite: string,
  cases: CaseLike[],
): Record<string, MetricSummary> {
  const live = cases.filter(scored);
  const names = [...new Set(live.flatMap((c) => Object.keys(c.scores)))];
  return Object.fromEntries(
    names.map((name) => {
      let points = live.map((c) => ({ value: c.scores[name]?.score, cluster: clusterOf(suite, c) }));
      if (sharedMetric(suite, name, live)) {
        const seen = new Set<string>();
        points = points.filter((p) => {
          if (typeof p.value !== "number" || seen.has(p.cluster)) return false;
          seen.add(p.cluster);
          return true;
        });
      }
      return [name, summarizeValues(points)];
    }),
  );
}

/**
 * The same summary for each value of a facet, when the cases carry two or
 * more values of it: research-targets' two strategies are two systems, and
 * their pooled mean describes neither.
 */
export function summarizeByFacet(
  suite: string,
  cases: CaseLike[],
  facet: string,
): Record<string, Record<string, MetricSummary>> | null {
  const values = [...new Set(cases.map((c) => facetOf(suite, c, facet)).filter((v): v is string => !!v))];
  if (values.length < 2) return null;
  return Object.fromEntries(
    values.sort().map((value) => [
      value,
      summarizeCases(
        suite,
        cases.filter((c) => facetOf(suite, c, facet) === value),
      ),
    ]),
  );
}

/* ── Paired comparison of two runs ───────────────────────────────── */

/** A seeded PRNG, so a Monte Carlo p-value is the same on every run. */
function mulberry32(seed: number): () => number {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

/**
 * Two-sided sign-flip (permutation) test that the paired differences are
 * centred on zero. `totals` holds one summed difference per cluster. Exact up
 * to 16 non-zero clusters, Monte Carlo beyond.
 */
export function signFlipP(totals: number[], draws = 20_000): number {
  const nonzero = totals.filter((d) => Math.abs(d) > 1e-12);
  const k = nonzero.length;
  if (k === 0) return 1;
  const observed = Math.abs(sum(nonzero)) - 1e-9;
  let extreme = 0;
  if (k <= 16) {
    const all = 1 << k;
    for (let mask = 0; mask < all; mask++) {
      let s = 0;
      for (let j = 0; j < k; j++) s += mask & (1 << j) ? -nonzero[j] : nonzero[j];
      if (Math.abs(s) >= observed) extreme++;
    }
    return extreme / all;
  }
  const random = mulberry32(0x7779e);
  for (let r = 0; r < draws; r++) {
    let s = 0;
    for (const d of nonzero) s += random() < 0.5 ? -d : d;
    if (Math.abs(s) >= observed) extreme++;
  }
  return (extreme + 1) / (draws + 1);
}

/** Benjamini-Hochberg adjusted p-values (q), nulls left in place. */
export function benjaminiHochberg(ps: Array<number | null>): Array<number | null> {
  const ranked = ps
    .map((p, i) => ({ p, i }))
    .filter((x): x is { p: number; i: number } => typeof x.p === "number")
    .sort((a, b) => a.p - b.p);
  const q: Array<number | null> = ps.map(() => null);
  let running = 1;
  for (let r = ranked.length - 1; r >= 0; r--) {
    running = Math.min(running, (ranked[r].p * ranked.length) / (r + 1));
    q[ranked[r].i] = running;
  }
  return q;
}

export interface MetricDelta {
  metric: string;
  /** Cases scored in both runs. */
  n: number;
  clusters: number;
  /** Means over the paired cases only. */
  base: number | null;
  next: number | null;
  delta: number | null;
  ci: [number, number] | null;
  /** Sign-flip test over clusters. */
  p: number | null;
  /** Benjamini-Hochberg across the metrics of this comparison. */
  q: number | null;
  /** Up or down beyond noise: the CI excludes zero and p < 0.05. */
  flag: "up" | "down" | null;
}

export interface Comparison {
  suite: string;
  base: string;
  next: string;
  /** Cases present in only one run are left out of every delta. */
  pairedCases: number;
  onlyBase: number;
  onlyNext: number;
  metrics: MetricDelta[];
}

export function comparePaired(
  suite: string,
  baseCases: CaseLike[],
  nextCases: CaseLike[],
  labels: { base: string; next: string } = { base: "baseline", next: "this run" },
): Comparison {
  const base = new Map(baseCases.filter(scored).map((c) => [c.case_id, c]));
  const next = new Map(nextCases.filter(scored).map((c) => [c.case_id, c]));
  const shared = [...next.keys()].filter((id) => base.has(id));
  const names = [
    ...new Set(
      shared.flatMap((id) => Object.keys(next.get(id)!.scores)).filter((name) =>
        shared.some((id) => base.get(id)!.scores[name] !== undefined),
      ),
    ),
  ];
  const metrics: MetricDelta[] = names.map((metric) => {
    const rows = shared.flatMap((id) => {
      const a = base.get(id)!.scores[metric]?.score;
      const b = next.get(id)!.scores[metric]?.score;
      return typeof a === "number" && typeof b === "number"
        ? [{ a, b, cluster: clusterOf(suite, next.get(id)!) }]
        : [];
    });
    if (!rows.length)
      return { metric, n: 0, clusters: 0, base: null, next: null, delta: null, ci: null, p: null, q: null, flag: null };
    const deltas = rows.map((r) => r.b - r.a);
    const clusters = rows.map((r) => r.cluster);
    const delta = average(deltas);
    const { se, clusters: g } = clusterSe(deltas, clusters);
    const totals = new Map<string, number>();
    rows.forEach((r, i) => totals.set(r.cluster, (totals.get(r.cluster) ?? 0) + deltas[i]));
    const p = signFlipP([...totals.values()]);
    // Scores live on 0..1, so no difference can leave −1..1.
    const ci: [number, number] | null =
      se === null
        ? null
        : [Math.max(-1, delta - tCritical(g - 1) * se), Math.min(1, delta + tCritical(g - 1) * se)];
    const beyond = ci !== null && p < 0.05 && (ci[0] > 0 || ci[1] < 0);
    return {
      metric,
      n: rows.length,
      clusters: g,
      base: average(rows.map((r) => r.a)),
      next: average(rows.map((r) => r.b)),
      delta,
      ci,
      p,
      q: null,
      flag: beyond ? (delta > 0 ? "up" : "down") : null,
    };
  });
  const q = benjaminiHochberg(metrics.map((m) => m.p));
  metrics.forEach((m, i) => (m.q = q[i]));
  return {
    suite,
    base: labels.base,
    next: labels.next,
    pairedCases: shared.length,
    onlyBase: [...base.keys()].filter((id) => !next.has(id)).length,
    onlyNext: [...next.keys()].filter((id) => !base.has(id)).length,
    metrics,
  };
}

/* ── Agreement between evaluators ────────────────────────────────── */

export function pearson(x: number[], y: number[]): number | null {
  const n = x.length;
  if (n < 3) return null;
  const mx = average(x);
  const my = average(y);
  let sxy = 0;
  let sxx = 0;
  let syy = 0;
  for (let i = 0; i < n; i++) {
    sxy += (x[i] - mx) * (y[i] - my);
    sxx += (x[i] - mx) ** 2;
    syy += (y[i] - my) ** 2;
  }
  return sxx > 0 && syy > 0 ? sxy / Math.sqrt(sxx * syy) : null;
}

function ranks(values: number[]): number[] {
  const order = values.map((v, i) => ({ v, i })).sort((a, b) => a.v - b.v);
  const out = new Array<number>(values.length);
  for (let i = 0; i < order.length; ) {
    let j = i;
    while (j + 1 < order.length && order[j + 1].v === order[i].v) j++;
    for (let k = i; k <= j; k++) out[order[k].i] = (i + j) / 2 + 1;
    i = j + 1;
  }
  return out;
}

export function spearman(x: number[], y: number[]): number | null {
  return pearson(ranks(x), ranks(y));
}

/** Fisher-z 95% interval for a correlation. */
export function correlationCi(r: number | null, n: number): [number, number] | null {
  if (r === null || n <= 3 || Math.abs(r) >= 1) return null;
  const z = Math.atanh(r);
  const half = Z95 / Math.sqrt(n - 3);
  return [Math.tanh(z - half), Math.tanh(z + half)];
}

/** Cohen's kappa after reading each value as pass (>= 0.5) or fail. */
export function kappa(x: number[], y: number[]): { agree: number | null; kappa: number | null } {
  const n = x.length;
  if (!n) return { agree: null, kappa: null };
  const a = x.map((v) => v >= 0.5);
  const b = y.map((v) => v >= 0.5);
  const agree = a.filter((v, i) => v === b[i]).length / n;
  const pa = a.filter(Boolean).length / n;
  const pb = b.filter(Boolean).length / n;
  const chance = pa * pb + (1 - pa) * (1 - pb);
  return { agree, kappa: chance < 1 ? (agree - chance) / (1 - chance) : null };
}

export interface AgreementPair {
  a: string;
  b: string;
  n: number;
  pearson: number | null;
  pearsonCi: [number, number] | null;
  spearman: number | null;
  /** Share of cases both evaluators put on the same side of 0.5. */
  agree: number | null;
  kappa: number | null;
  /** Mean of a − b: which evaluator reads higher. */
  meanDiff: number | null;
}

export function agreementPair(a: string, b: string, x: number[], y: number[]): AgreementPair {
  const r = pearson(x, y);
  const { agree, kappa: k } = kappa(x, y);
  return {
    a,
    b,
    n: x.length,
    pearson: r,
    pearsonCi: correlationCi(r, x.length),
    spearman: spearman(x, y),
    agree,
    kappa: k,
    meanDiff: x.length ? average(x.map((v, i) => v - y[i])) : null,
  };
}

/**
 * How well a reading separates known-good from known-bad cases: the chance a
 * random good case outscores a random bad one (ties count half).
 */
export function auc(good: number[], bad: number[]): number | null {
  if (!good.length || !bad.length) return null;
  let wins = 0;
  for (const g of good) for (const b of bad) wins += g > b ? 1 : g === b ? 0.5 : 0;
  return wins / (good.length * bad.length);
}

/* ── Repeatability across repeated runs ──────────────────────────── */

export interface Repeatability {
  metric: string;
  runs: number;
  /** Cases scored in every run. */
  cases: number;
  runMeans: number[];
  /** Standard deviation of the suite mean from run to run. */
  sdOfRunMeans: number | null;
  /** Pooled standard deviation of one case's score across runs. */
  withinCaseSd: number | null;
  /** What run-to-run noise alone does to a suite mean: withinCaseSd / √cases. */
  noiseSe: number | null;
  /** ICC(1): the share of score variance due to real differences between cases. */
  icc: number | null;
}

export function repeatability(runs: CaseLike[][]): Repeatability[] {
  const k = runs.length;
  if (k < 2) return [];
  const byId = runs.map((cases) => new Map(cases.filter(scored).map((c) => [c.case_id, c])));
  const names = [...new Set(runs.flatMap((cases) => cases.flatMap((c) => Object.keys(c.scores))))];
  return names.map((metric) => {
    const ids = [...byId[0].keys()].filter((id) =>
      byId.every((m) => typeof m.get(id)?.scores[metric]?.score === "number"),
    );
    const grid = ids.map((id) => byId.map((m) => m.get(id)!.scores[metric].score as number));
    const n = grid.length;
    const runMeans = byId.map((_, r) => (n ? average(grid.map((row) => row[r])) : Number.NaN));
    if (n < 2)
      return { metric, runs: k, cases: n, runMeans, sdOfRunMeans: null, withinCaseSd: null, noiseSe: null, icc: null };
    const caseMeans = grid.map(average);
    const grand = average(caseMeans);
    const msw = sum(grid.map((row, i) => sum(row.map((v) => (v - caseMeans[i]) ** 2)))) / (n * (k - 1));
    const msb = (k * sum(caseMeans.map((m) => (m - grand) ** 2))) / (n - 1);
    const denominator = msb + (k - 1) * msw;
    return {
      metric,
      runs: k,
      cases: n,
      runMeans,
      sdOfRunMeans: sampleSd(runMeans),
      withinCaseSd: Math.sqrt(msw),
      noiseSe: Math.sqrt(msw / n),
      icc: denominator > 0 ? (msb - msw) / denominator : null,
    };
  });
}

/* ── Formatting ──────────────────────────────────────────────────── */

const fixed = (x: number | null | undefined, digits = 2) =>
  typeof x === "number" && Number.isFinite(x) ? x.toFixed(digits) : "-";
const signed = (x: number | null | undefined, digits = 2) =>
  typeof x === "number" && Number.isFinite(x) ? `${x >= 0 ? "+" : "−"}${Math.abs(x).toFixed(digits)}` : "-";

export function formatInterval(ci: [number, number] | null | undefined, sign = false): string {
  if (!ci) return "";
  const f = sign ? signed : fixed;
  return `[${f(ci[0])}, ${f(ci[1])}]`;
}

/** One printed line per metric: mean, 95% interval, cases and clusters. */
export function formatSummaryLines(summary: Record<string, MetricSummary>): string[] {
  return Object.entries(summary).map(([name, s]) => {
    const mean = s.mean === null ? "   -" : s.mean.toFixed(2);
    const ci = formatInterval(s.ci).padEnd(14);
    const units =
      s.clusters !== undefined && s.clusters < s.n
        ? `n=${s.n}, ${s.clusters} cluster${s.clusters === 1 ? "" : "s"}`
        : `n=${s.n}`;
    return `  ${name.padEnd(24)} ${mean}  ${ci} (${units})`;
  });
}

export function formatComparison(comparison: Comparison): string[] {
  const lines = [
    `  vs ${comparison.base}: ${comparison.pairedCases} case(s) paired by case_id` +
      (comparison.onlyBase || comparison.onlyNext
        ? ` (${comparison.onlyBase} only in the baseline, ${comparison.onlyNext} only here)`
        : ""),
    `    ${"metric".padEnd(24)} ${"base".padStart(5)} ${"now".padStart(5)} ${"Δ".padStart(6)}  ${"95% CI".padEnd(16)} ${"p".padStart(5)}`,
  ];
  if (comparison.metrics.some((m) => m.n > 0 && m.clusters < 5))
    lines.push("    (fewer than five clusters paired: intervals are too wide to call any change)");
  for (const m of comparison.metrics) {
    const mark = m.flag === "up" ? "▲" : m.flag === "down" ? "▼" : "";
    lines.push(
      `    ${m.metric.padEnd(24)} ${fixed(m.base).padStart(5)} ${fixed(m.next).padStart(5)} ${signed(m.delta).padStart(6)}  ${formatInterval(m.ci, true).padEnd(16)} ${fixed(m.p).padStart(5)} ${mark}`.trimEnd(),
    );
  }
  const moved = comparison.metrics.filter((m) => m.flag);
  const survive = moved.filter((m) => (m.q ?? 1) < 0.05);
  lines.push(
    `    ${moved.length} of ${comparison.metrics.length} metric(s) moved beyond noise (CI excludes 0 and sign-flip p < 0.05)` +
      (moved.length ? `; ${survive.length} survive Benjamini-Hochberg at q < 0.05` : ""),
  );
  return lines;
}

export function formatRepeatability(rows: Repeatability[]): string[] {
  if (!rows.length) return [];
  const lines = [
    `  run-to-run variance over ${rows[0].runs} runs`,
    `    ${"metric".padEnd(24)} ${"run means".padEnd(22)} ${"sd(mean)".padStart(8)} ${"case sd".padStart(8)} ${"noise se".padStart(8)} ${"icc".padStart(5)}`,
  ];
  for (const r of rows)
    lines.push(
      `    ${r.metric.padEnd(24)} ${r.runMeans.map((m) => fixed(m)).join(" ").padEnd(22)} ${fixed(r.sdOfRunMeans, 3).padStart(8)} ${fixed(r.withinCaseSd, 3).padStart(8)} ${fixed(r.noiseSe, 3).padStart(8)} ${fixed(r.icc).padStart(5)}`,
    );
  return lines;
}
"}

item.aggregated_output:
/**
 * Arize hand-off for the app evals: datasets, experiments and traces.
 *
 * Datasets and experiments go through the `ax` CLI, which owns Arize
 * authentication (`ax profiles`). Each suite's corpus becomes a dataset named
 * for its content hash, so an experiment is always tied to the exact cases it
 * ran; editing a corpus starts a new dataset rather than silently changing an
 * old one. Runs are uploaded with flat `eval.<name>.score|label|explanation`
 * columns, which Arize reads as evaluation results.
 *
 * Traces go through the app's own OpenInference exporter
 * (`convex/arizeTracing.ts`): the local app is started with the Arize keys in
 * its environment, and each case runs inside a CHAIN span, so every model call
 * the app makes for that case lands in one trace.
 */
import { spawn } from "node:child_process";
import { createHash } from "node:crypto";
import { mkdtemp, rm, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { SpanStatusCode, trace } from "@opentelemetry/api";
import type { Score } from "./scoring";

export interface AxOptions {
  space: string;
}

async function ax(args: string[], stdin?: string): Promise<string> {
  const child = spawn("ax", [...args], { stdio: ["pipe", "pipe", "pipe"] });
  let stdout = "";
  let stderr = "";
  child.stdout.on("data", (chunk) => (stdout += chunk));
  child.stderr.on("data", (chunk) => (stderr += chunk));
  child.stdin.end(stdin ?? "");
  const code = await new Promise<number>((done) =>
    child.on("close", (exit) => done(exit ?? 1)),
  );
  if (code !== 0) {
    const detail = (stderr || stdout).replace(/\s+/g, " ").trim().slice(0, 400);
    throw new Error(`ax ${args.slice(0, 2).join(" ")} failed: ${detail}`);
  }
  return stdout;
}

/** `ax -o json` prints the payload after any status lines. */
function jsonFrom(output: string): unknown {
  const start = output.search(/[[{]/);
  if (start < 0) throw new Error("ax returned no JSON");
  return JSON.parse(output.slice(start));
}

export function corpusHash(rows: unknown[]): string {
  return createHash("sha256").update(JSON.stringify(rows)).digest("hex").slice(0, 8);
}

/**
 * Find or create the dataset for a corpus. Returns the dataset ID and a map
 * from case_id to Arize example ID.
 */
export async function ensureDataset(
  options: AxOptions,
  name: string,
  rows: Array<Record<string, string | number | boolean> & { case_id: string }>,
): Promise<{ id: string; name: string; examples: Map<string, string> }> {
  let id: string | null = null;
  try {
    const found = jsonFrom(
      await ax(["datasets", "get", name, "--space", options.space, "-o", "json"]),
    ) as { id?: string };
    id = found.id ?? null;
  } catch {
    id = null;
  }
  if (!id) {
    const created = jsonFrom(
      await ax(
        ["datasets", "create", "--name", name, "--space", options.space, "--file", "-", "-o", "json"],
        JSON.stringify(rows),
      ),
    ) as { id?: string };
    if (!created.id) throw new Error(`ax did not return an ID for dataset ${name}`);
    id = created.id;
  }
  const exported = jsonFrom(
    await ax(["datasets", "export", id, "--stdout"]),
  ) as Array<{ id: string; additional_properties?: { case_id?: string } }>;
  const examples = new Map<string, string>();
  for (const example of exported) {
    const caseId = example.additional_properties?.case_id;
    if (caseId) examples.set(caseId, example.id);
  }
  return { id, name, examples };
}

export interface ExperimentRun {
  example_id: string;
  output: string;
  /** False when the case errored before it could be scored. */
  ok: boolean;
  error?: string;
  scores: Record<string, Score>;
  metadata: Record<string, string | number | null>;
}

/**
 * Arize wants a number in every row of an `eval.<name>.score` column, so the
 * runs are made rectangular before upload:
 *
 *  - a case that errored scores 0 on every metric, labelled "error": the
 *    writer got nothing, which is what the eval should show;
 *  - a metric that does not apply to some cases (weakness recall on a strong
 *    draft) is uploaded as labels, with "n/a" where it does not apply, rather
 *    than inventing a number. The local report keeps the scores either way.
 */
export function experimentRows(runs: ExperimentRun[]): {
  rows: Array<Record<string, unknown>>;
  labelOnly: string[];
} {
  const names = [...new Set(runs.flatMap((run) => Object.keys(run.scores)))];
  const labelOnly = names.filter((name) =>
    runs.some((run) => run.ok && typeof run.scores[name]?.score !== "number"),
  );
  const failed = runs.some((run) => !run.ok);
  // `ax` reads the file with pandas, which turns "1.00" into a number; a label
  // column must stay text, so labels are words or prefixed, never bare digits.
  const withLabel = names.filter(
    (name) =>
      failed ||
      labelOnly.includes(name) ||
      runs.some((run) => run.ok && run.scores[name]?.label),
  );
  const metadataKeys = [
    ...new Set(runs.flatMap((run) => Object.keys(run.metadata))),
  ];
  const rows = runs.map((run) => {
    const row: Record<string, unknown> = {
      example_id: run.example_id,
      output: run.output,
    };
    for (const name of names) {
      const score = run.scores[name];
      if (!run.ok) {
        if (!labelOnly.includes(name)) row[`eval.${name}.score`] = 0;
        row[`eval.${name}.label`] = "error";
        row[`eval.${name}.explanation`] = run.error ?? "the case did not run";
        continue;
      }
      if (!labelOnly.includes(name)) row[`eval.${name}.score`] = score?.score;
      if (withLabel.includes(name))
        row[`eval.${name}.label`] =
          score?.label ??
          (!labelOnly.includes(name)
            ? ""
            : typeof score?.score === "number"
              ? `score ${score.score.toFixed(2)}`
              : "n/a");
      row[`eval.${name}.explanation`] = score?.explanation ?? "";
    }
    for (const key of metadataKeys) row[key] = run.metadata[key] ?? "";
    return row;
  });
  return { rows, labelOnly };
}

export async function uploadExperiment(
  datasetId: string,
  name: string,
  runs: ExperimentRun[],
): Promise<{ id: string | null; labelOnly: string[] }> {
  const { rows, labelOnly } = experimentRows(runs);
  const dir = await mkdtemp(join(tmpdir(), "twyne-arize-"));
  try {
    const file = join(dir, "runs.json");
    await writeFile(file, JSON.stringify(rows));
    const created = jsonFrom(
      await ax([
        "experiments",
        "create",
        "--name",
        name,
        "--dataset",
        datasetId,
        "--file",
        file,
        "-o",
        "json",
      ]),
    ) as { id?: string };
    return { id: created.id ?? null, labelOnly };
  } finally {
    await rm(dir, { recursive: true, force: true });
  }
}

/**
 * Run `task` inside an OpenInference CHAIN span named for the case. The span
 * is a no-op unless the app's Arize tracer has been registered.
 */
export async function withCaseSpan<T>(
  attributes: { suite: string; caseId: string; experiment: string; input: string },
  task: () => Promise<{ value: T; output: string }>,
): Promise<{ value: T; traceId: string | null }> {
  const tracer = trace.getTracer("twyne-app-evals");
  return tracer.startActiveSpan(
    `eval.${attributes.suite}`,
    {
      attributes: {
        "openinference.span.kind": "CHAIN",
        // The OpenInference processor re-roots AI SDK spans whose parent does
        // not look like AI; an `ai.*` key keeps the case's model calls nested.
        "ai.telemetry.functionId": `eval.${attributes.suite}`,
        "input.value": attributes.input,
        "twyne.eval.suite": attributes.suite,
        "twyne.eval.case_id": attributes.caseId,
        "twyne.eval.experiment": attributes.experiment,
      },
    },
    async (span) => {
      const context = span.spanContext();
      const traceId = context.traceFlags ? context.traceId : null;
      try {
        const { value, output } = await task();
        span.setAttribute("output.value", output);
        span.setStatus({ code: SpanStatusCode.OK });
        return { value, traceId };
      } catch (error) {
        span.recordException(error as Error);
        span.setStatus({
          code: SpanStatusCode.ERROR,
          message: error instanceof Error ? error.message : String(error),
        });
        throw error;
      } finally {
        span.end();
      }
    },
  );
}
/**
 * Reading app eval reports back: for `--baseline`, and for `compare.ts`.
 *
 * A report spec is a report file, a directory of them, or a path prefix
 * (`reports/app-evals/notorganic-fixed-20261023` picks up every suite of that
 * run). Several reports of one suite, such as the rounds of `--repeat`, merge
 * into one case per case_id holding each metric's mean across the runs, which
 * is the less noisy baseline to compare against.
 */
import { existsSync, readdirSync, readFileSync, statSync } from "node:fs";
import { basename, dirname, join } from "node:path";
import type { CaseLike } from "./stats";

/** The parts of a report this module reads; run.ts's SuiteReport fits it. */
export interface ReportLike {
  suite: string;
  experiment?: string;
  model?: string;
  judge?: string;
  startedAt?: string;
  cases: CaseLike[];
}

export function reportPaths(spec: string): string[] {
  if (existsSync(spec) && statSync(spec).isDirectory())
    return readdirSync(spec)
      .filter((name) => name.endsWith(".json") && !name.endsWith("-repeatability.json"))
      .sort()
      .map((name) => join(spec, name));
  if (existsSync(spec)) return [spec];
  const dir = dirname(spec);
  const prefix = basename(spec);
  if (!existsSync(dir)) return [];
  return readdirSync(dir)
    .filter((name) => name.startsWith(prefix) && name.endsWith(".json") && !name.endsWith("-repeatability.json"))
    .sort()
    .map((name) => join(dir, name));
}

export function readReports(specs: string[]): ReportLike[] {
  const paths = [...new Set(specs.flatMap(reportPaths))];
  if (!paths.length) throw new Error(`No reports found for ${specs.join(", ")}`);
  return paths.flatMap((path) => {
    const parsed = JSON.parse(readFileSync(path, "utf8")) as ReportLike | ReportLike[];
    const list = Array.isArray(parsed) ? parsed : [parsed];
    return list.filter((r) => r && typeof r.suite === "string" && Array.isArray(r.cases));
  });
}

export function bySuite(reports: ReportLike[]): Map<string, ReportLike[]> {
  const out = new Map<string, ReportLike[]>();
  for (const report of reports) out.set(report.suite, [...(out.get(report.suite) ?? []), report]);
  return out;
}

/**
 * One case per case_id across several runs of a suite: each metric's score
 * is its mean over the runs that scored it. Labels, items and raw output are
 * the first run's.
 */
export function averageRuns(reports: ReportLike[]): CaseLike[] {
  if (reports.length === 1) return reports[0].cases;
  const merged = new Map<string, { first: CaseLike; sums: Map<string, { total: number; n: number }> }>();
  for (const report of reports)
    for (const c of report.cases) {
      if (c.skipped) continue;
      const entry = merged.get(c.case_id) ?? { first: c, sums: new Map() };
      for (const [name, score] of Object.entries(c.scores)) {
        if (typeof score?.score !== "number") continue;
        const sum = entry.sums.get(name) ?? { total: 0, n: 0 };
        sum.total += score.score;
        sum.n += 1;
        entry.sums.set(name, sum);
      }
      merged.set(c.case_id, entry);
    }
  return [...merged.values()].map(({ first, sums }) => ({
    ...first,
    scores: Object.fromEntries(
      [...new Set([...Object.keys(first.scores), ...sums.keys()])].map((name) => {
        const sum = sums.get(name);
        const score = first.scores[name] ?? { score: null };
        return [name, sum ? { ...score, score: sum.total / sum.n } : score];
      }),
    ),
  }));
}

export function describe(reports: ReportLike[]): string {
  const first = reports[0];
  const name = first.experiment ?? first.suite;
  return reports.length > 1 ? `${name} (+${reports.length - 1} more run(s), averaged)` : name;
}

/**
 * App evals: Twyne's model-backed features, driven through MCP and the CLI.
 *
 *   bun run eval:app                                  # every suite, mock model
 *   bun run eval:app -- --suite room --model notorganic --judge notorganic --arize --trace
 *   bun run eval:app -- --target live --suite rubric  # a deployment, via TWYNE_API_URL
 *
 * See evals/app/README.md for the suites, the scores and the Arize hand-off.
 */
import { mkdir, writeFile } from "node:fs/promises";
import { join } from "node:path";
import { fileURLToPath } from "node:url";
import { parseArgs } from "node:util";
import { agreementFor, formatAgreement, type ConstructResult } from "./agreement";
import {
  corpusHash,
  ensureDataset,
  uploadExperiment,
  withCaseSpan,
  type ExperimentRun,
} from "./arize";
import { connectMcp, type Connection, type McpDriver } from "./drivers";
import { createJudge, type ClairicAsk, type JevAsk, type JudgeMode } from "./judges";
import {
  startLocalApp,
  type AppModelMode,
  type LocalApp,
  type ResearchMode,
  type SystemOneMode,
  type UsageTotals,
} from "./local-app";
import { averageRuns, bySuite, describe, readReports, type ReportLike } from "./reports";
import { TwyneClient } from "../../packages/twyne-tools/src/client";
import type { Score } from "./scoring";
import {
  comparePaired,
  formatComparison,
  formatRepeatability,
  formatSummaryLines,
  repeatability,
  summarizeByFacet,
  summarizeCases,
  type Comparison,
  type MetricSummary,
  type Repeatability,
} from "./stats";
import { dossierSuite } from "./suites/dossier";
import { interviewSuite } from "./suites/interview";
import { researchSourcesSuite, researchTargetsSuite } from "./suites/research";
import { roomSuite } from "./suites/room";
import { rewriteSuite } from "./suites/rewrite";
import { rubricSuite } from "./suites/rubric";
import type { ScoredCase, Suite } from "./suites/types";

const SUITES = {
  room: roomSuite,
  rubric: rubricSuite,
  rewrite: rewriteSuite,
  dossier: dossierSuite,
  interview: interviewSuite,
  "research-targets": researchTargetsSuite,
  "research-sources": researchSourcesSuite,
} as const satisfies Record<string, Suite<{ case_id: string }>>;

type SuiteName = keyof typeof SUITES;

const HELP = `Twyne app evals

Usage: bun evals/app/run.ts [options]

  --suite NAMES        room, rubric, rewrite, dossier, interview, research-targets,
                       research-sources, or all (default all)
  --target local|live  in-process app (default) or TWYNE_API_URL + TWYNE_ACCESS_TOKEN
  --model MODE         local app's hosted model: mock (default), openai-compatible, notorganic
  --system-one MODE    review-gate judgements: mock, direct (TYPESAFE_API_KEY) or off
                       (default: mock with the mock model, direct when a key is set)
  --research MODE      auto-research search: mock, notorganic, keenable (KEENABLE_API_KEY),
                       custom (TWYNE_APP_SEARCH_URL) or off
                       (default: mock with the mock model, notorganic with notorganic)
  --driver mcp|mcp-stdio  MCP in-process (default) or twyne-mcp over stdio
  --judge MODE         none (default), notorganic, openai-compatible
  --jev                add Jev (calibrated judgements) and Clairic (typed extraction)
                       evaluators, asked through the app's own System One and extraction
  --case IDS           only these case_ids (comma-separated)
  --limit N            first N cases per suite
  --concurrency N      cases in flight per suite (default 2)
  --repeat N           run each suite N times and report run-to-run variance
                       (experiments end -r1..-rN; costs N times as much)
  --baseline SPECS     compare with earlier reports, paired by case_id: report files,
                       directories or a path prefix (comma-separated); several runs of
                       one suite are averaged per case
  --arize              upload each suite as an Arize dataset + experiment (ax CLI)
  --arize-space ID     Arize space (default ARIZE_SPACE_ID)
  --trace              export the app's spans to Arize (ARIZE_API_KEY, ARIZE_SPACE_ID)
  --project NAME       Arize tracing project (default twyne-app-evals)
  --experiment NAME    experiment name prefix (default app-<suite>-<model>-<time>)
  --out DIR            report directory (default reports/app-evals)
  --strict             exit 1 when any case fails to run

Compare reports after the fact with evals/app/compare.ts.
`;

export interface SuiteReport {
  suite: string;
  surface: string;
  experiment: string;
  target: string;
  model: string;
  driver: string;
  judge: string;
  /** Whether Jev and Clairic evaluators ran. */
  jev?: boolean;
  startedAt: string;
  /** With `--repeat`: which round this is. */
  round?: { index: number; of: number };
  /**
   * Each metric's mean with its 95% interval. Cases that share a draft or a
   * pair count as one cluster, so `clusters` is the effective sample size.
   */
  summary: Record<string, MetricSummary>;
  /** The summary per strategy, where a suite runs more than one. */
  byStrategy?: Record<string, Record<string, MetricSummary>>;
  errors: number;
  /** Hosted calls the in-process app made for this suite. */
  usage?: Omit<UsageTotals, "costMicrousd"> & { costMicrousd: number | null };
  /** What Not Organic billed for the suite (notorganic mode only). */
  billed?: { microusd: number; settled: number; unresolved: number } | null;
  arize?: { dataset: string; datasetId: string; experimentId: string | null };
  /** Evaluators that read the same construct, compared on shared cases. */
  agreement?: ConstructResult[];
  /** `--baseline`: this run (all rounds, averaged) against the baseline. */
  comparison?: Comparison;
  /** `--repeat`: variance across the rounds, on the last round's report. */
  repeatability?: Repeatability[];
  cases: Array<{
    case_id: string;
    /** Cases in one cluster (a strong/weak pair, one draft) are not independent. */
    cluster: string;
    /** Case attributes to slice by: quality, strategy, level, persona, mode. */
    facets?: Record<string, string>;
    ok: boolean;
    /** Never started: the run stopped after repeated provider failures. */
    skipped?: boolean;
    error?: string;
    latencyMs: number;
    traceId: string | null;
    scores: Record<string, Score>;
    output: string;
    raw: unknown;
  }>;
}

export interface RunOptions {
  suites: SuiteName[];
  target: "local" | "live";
  model: AppModelMode;
  systemOne?: SystemOneMode;
  research?: ResearchMode;
  driver: McpDriver["kind"];
  judge: JudgeMode;
  /** Add Jev and Clairic evaluators (through the app's own paths). */
  jev?: boolean;
  caseIds?: string[];
  limit?: number;
  concurrency: number;
  /** Run each suite this many times and report run-to-run variance. */
  repeat?: number;
  /** Earlier reports to compare with: files, directories or prefixes. */
  baseline?: string[];
  arize: boolean;
  arizeSpace?: string;
  trace: boolean;
  project: string;
  experiment?: string;
  out?: string;
  env: Readonly<Record<string, string | undefined>>;
  log?: (line: string) => void;
}

async function pool<T, R>(
  items: T[],
  limit: number,
  worker: (item: T) => Promise<R>,
): Promise<R[]> {
  const results: R[] = new Array(items.length);
  let next = 0;
  const lanes = Array.from({ length: Math.max(1, Math.min(limit, items.length)) }, async () => {
    while (next < items.length) {
      const index = next++;
      results[index] = await worker(items[index]);
    }
  });
  await Promise.all(lanes);
  return results;
}

function stamp(): string {
  return new Date().toISOString().replace(/[-:]/g, "").replace(/\..+/, "").replace("T", "-");
}

const sleep = (ms: number) => new Promise((done) => setTimeout(done, ms));

/** Rate limits are per writer, so a live run retries what the limiter refused. */
async function withRetry<T>(live: boolean, task: () => Promise<T>): Promise<T> {
  for (let attempt = 0; ; attempt++) {
    try {
      return await task();
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error);
      if (!live || attempt >= 3 || !/rate|429|too many|slow down/i.test(message))
        throw error;
      await sleep(20_000 * (attempt + 1));
    }
  }
}

const RETRYABLE = /too many requests|rate limited|overloaded/i;

/**
 * Jev and Clairic share one evaluator writer, whose rate limit (20 a minute
 * on the free tier) a large suite can outrun. A refusal waits out the window
 * the limiter names instead of becoming a jev-error.
 */
async function patiently<T extends { ok: boolean; error?: string }>(task: () => Promise<T>): Promise<T> {
  for (let attempt = 0; ; attempt++) {
    let message: string;
    try {
      const value = await task();
      if (value.ok || !RETRYABLE.test(value.error ?? "") || attempt >= 4) return value;
      message = value.error ?? "";
    } catch (error) {
      message = error instanceof Error ? error.message : String(error);
      if (!RETRYABLE.test(message) || attempt >= 4) throw error;
    }
    const seconds = Number(message.match(/in (\d+)\s*s/)?.[1]);
    await sleep((Number.isFinite(seconds) ? seconds + 1 : 10 * (attempt + 1)) * 1000);
  }
}

/** Case attributes worth slicing a suite by, where a corpus has them. */
const FACETS = ["quality", "strategy", "level", "personaId", "mode", "expectedBehavior", "genre", "kind"];

function caseMeta(testCase: { case_id: string }): { cluster: string; facets?: Record<string, string> } {
  const fields = testCase as unknown as Record<string, unknown>;
  const cluster = [fields.cluster, fields.pair_id, fields.draft_id].find(
    (v): v is string => typeof v === "string" && v.length > 0,
  );
  const facets = Object.fromEntries(
    FACETS.filter((key) => typeof fields[key] === "string").map((key) => [key, fields[key] as string]),
  );
  return {
    cluster: cluster ?? testCase.case_id,
    ...(Object.keys(facets).length ? { facets } : {}),
  };
}

function printReport(report: SuiteReport, log: (line: string) => void): void {
  const round = report.round ? ` (round ${report.round.index} of ${report.round.of})` : "";
  log(
    `\n${report.suite}${round} — ${report.surface} — ${report.cases.length} case(s), ${report.errors} error(s)`,
  );
  if (report.usage?.calls)
    log(
      `  hosted calls ${report.usage.calls}, tokens ${report.usage.inputTokens} in / ${report.usage.outputTokens} out` +
        (report.usage.costMicrousd !== null
          ? `, est. $${(report.usage.costMicrousd / 1e6).toFixed(4)}`
          : ""),
    );
  if (report.billed)
    log(
      `  billed by Not Organic $${(report.billed.microusd / 1e6).toFixed(4)} (${report.billed.settled} settled` +
        (report.billed.unresolved ? `, ${report.billed.unresolved} still settling` : "") +
        ")",
    );
  log(`  ${"metric".padEnd(24)} mean  95% CI`);
  for (const line of formatSummaryLines(report.summary)) log(line);
  for (const [strategy, summary] of Object.entries(report.byStrategy ?? {})) {
    log(`  strategy ${strategy}`);
    for (const line of formatSummaryLines(summary)) log(`  ${line}`);
  }
  for (const failed of report.cases.filter((c) => !c.ok && !c.skipped))
    log(`  ✗ ${failed.case_id}: ${failed.error}`);
  const skipped = report.cases.filter((c) => c.skipped).length;
  if (skipped) log(`  ⏸ ${skipped} case(s) not run: ${report.cases.find((c) => c.skipped)?.error}`);
  for (const line of formatAgreement(report.agreement ?? [])) log(line);
}

export async function runAppEvals(options: RunOptions): Promise<SuiteReport[]> {
  const log = options.log ?? ((line: string) => console.log(line));
  const live = options.target === "live";
  const arizeSpace = options.arizeSpace ?? options.env.ARIZE_SPACE_ID;
  if (options.arize && !arizeSpace)
    throw new Error("--arize needs --arize-space or ARIZE_SPACE_ID");
  const rounds = Math.max(1, Math.floor(options.repeat ?? 1));
  // Read the baseline first: a typo should fail before any money is spent.
  const baseline = options.baseline?.length ? bySuite(readReports(options.baseline)) : null;

  const tracing = options.trace
    ? {
        apiKey: options.env.ARIZE_API_KEY ?? "",
        spaceId: options.env.ARIZE_SPACE_ID ?? "",
        projectName: options.project,
        region: options.env.ARIZE_REGION,
      }
    : null;
  if (tracing && (!tracing.apiKey || !tracing.spaceId))
    throw new Error("--trace needs ARIZE_API_KEY and ARIZE_SPACE_ID");

  const judge = createJudge(options.judge, options.env);
  let app: LocalApp | null = null;
  let shared: Connection | null = null;
  if (live) {
    const apiUrl = options.env.TWYNE_API_URL;
    const token = options.env.TWYNE_ACCESS_TOKEN;
    if (!apiUrl || !token)
      throw new Error("--target live needs TWYNE_API_URL and TWYNE_ACCESS_TOKEN");
    shared = { apiUrl, token };
    if (tracing) {
      process.env.ARIZE_API_KEY = tracing.apiKey;
      process.env.ARIZE_SPACE_ID = tracing.spaceId;
      process.env.ARIZE_PROJECT_NAME = tracing.projectName;
      if (tracing.region) process.env.ARIZE_REGION = tracing.region;
    }
  } else {
    app = await startLocalApp({
      model: options.model,
      systemOne: options.systemOne,
      research: options.research,
      env: options.env,
      tracing,
    });
  }
  // Registers the OpenInference exporter when the Arize keys are present.
  const { flushArize } = await import("../../convex/arizeTracing");

  const modelLabel = live ? "deployment" : (app?.modelLabel ?? options.model);
  if (options.jev && !app)
    throw new Error("--jev runs Jev and Clairic through the in-process app; use --target local");
  const evaluator = options.jev && app ? app : null;
  const scoreContext = {
    judge,
    jev: evaluator ? ((request) => patiently(() => evaluator.judge(request))) as JevAsk : null,
    extract: evaluator ? ((request) => patiently(() => evaluator.extract(request))) as ClairicAsk : null,
  };
  const reports: SuiteReport[] = [];
  // Out of credit and an outage look the same from here: the app reports the
  // provider unavailable. Three in a row stops the suite, so a drained wallet
  // ends it cleanly instead of filling the experiment with failures.
  let providerFailures = 0;
  let stopped: string | null = null;

  const writeReport = async (report: SuiteReport) => {
    if (!options.out) return;
    await mkdir(options.out, { recursive: true });
    await writeFile(join(options.out, `${report.experiment}.json`), JSON.stringify(report, null, 2));
  };

  try {
    for (const suiteName of options.suites) {
      const suite = SUITES[suiteName] as Suite<{ case_id: string }>;
      let cases = suite.load();
      if (options.caseIds?.length)
        cases = cases.filter((c) => options.caseIds?.includes(c.case_id));
      if (options.limit) cases = cases.slice(0, options.limit);
      if (cases.length === 0) continue;

      const base =
        options.experiment
          ? `${options.experiment}-${suiteName}`
          : `app-${suiteName}-${options.target === "live" ? "live" : options.model}-${stamp()}`;
      const suiteReports: SuiteReport[] = [];

      for (let round = 1; round <= rounds; round++) {
        // A provider that fails one suite's alias can still serve the next.
        providerFailures = 0;
        stopped = null;
        const experiment = rounds > 1 ? `${base}-r${round}` : base;
        log(
          `▸ ${suiteName}${rounds > 1 ? ` (round ${round} of ${rounds})` : ""}: ${cases.length} case(s) via ${suite.surface} → ${modelLabel}`,
        );

        const usageBefore = await app?.usage();
        const suiteStarted = Date.now();
        let sharedMcp: McpDriver | null = null;
        if (shared) sharedMcp = await connectMcp(shared, options.driver);

        type CaseResult = SuiteReport["cases"][number] & { testCase: { case_id: string } };
        const runs = await pool(cases, live ? 1 : options.concurrency, async (testCase): Promise<CaseResult> => {
          const meta = caseMeta(testCase);
          if (stopped)
            return {
              case_id: testCase.case_id,
              ...meta,
              testCase,
              ok: false,
              skipped: true,
              error: stopped,
              latencyMs: 0,
              traceId: null,
              scores: {} as Record<string, Score>,
              output: `[skipped] ${stopped}`,
              raw: null,
            };
          const connection: Connection = shared ?? {
            apiUrl: app!.url,
            token: (await app!.newWriter(testCase.case_id)).token,
            ...(options.driver === "mcp" ? { fetch: app!.fetch } : {}),
          };
          const mcp = sharedMcp ?? (await connectMcp(connection, options.driver));
          const started = Date.now();
          try {
            const { value, traceId } = await withCaseSpan(
              {
                suite: suiteName,
                caseId: testCase.case_id,
                experiment,
                input: JSON.stringify(suite.example(testCase)).slice(0, 20_000),
              },
              async () => {
                const client = new TwyneClient({
                  apiUrl: connection.apiUrl,
                  accessToken: connection.token,
                  fetch: connection.fetch,
                });
                const run = await withRetry(live, () =>
                  suite.run({ mcp, connection, client }, testCase),
                );
                return { value: run, output: run.output };
              },
            );
            const latencyMs = Date.now() - started;
            const scores = await suite.score(scoreContext, testCase, value.raw);
            providerFailures = 0;
            log(`  ✓ ${testCase.case_id} (${(latencyMs / 1000).toFixed(1)}s)`);
            return {
              case_id: testCase.case_id,
              ...meta,
              testCase,
              ok: true,
              latencyMs,
              traceId,
              scores,
              output: value.output,
              raw: value.raw,
            };
          } catch (error) {
            const message = error instanceof Error ? error.message : String(error);
            log(`  ✗ ${testCase.case_id}: ${message}`);
            if (/unavailable|insufficient|quota|credit|402/i.test(message)) {
              providerFailures += 1;
              if (providerFailures >= 3)
                stopped = "stopped after 3 consecutive provider failures (out of credit or provider down)";
            }
            return {
              case_id: testCase.case_id,
              ...meta,
              testCase,
              ok: false,
              error: message,
              latencyMs: Date.now() - started,
              traceId: null,
              scores: {} as Record<string, Score>,
              output: `[error] ${message}`,
              raw: null,
            };
          } finally {
            if (!sharedMcp) await mcp.close();
          }
        });
        await sharedMcp?.close();

        const scored: Array<ScoredCase<{ case_id: string }>> = runs
          .filter((r) => r.ok)
          .map((r) => ({ case: r.testCase, raw: r.raw, scores: r.scores }));
        suite.scoreAll?.(scored);
        for (const r of runs)
          if (!r.skipped)
            r.scores.harness = { score: r.ok ? 1 : 0, label: r.ok ? "ran" : "error", explanation: r.error };

        const report: SuiteReport = {
          suite: suiteName,
          surface: suite.surface,
          experiment,
          target: options.target,
          model: modelLabel,
          driver: options.driver,
          judge: judge?.label ?? "none",
          jev: !!evaluator,
          startedAt: new Date().toISOString(),
          ...(rounds > 1 ? { round: { index: round, of: rounds } } : {}),
          summary: {},
          errors: runs.filter((r) => !r.ok && !r.skipped).length,
          cases: runs.map(({ testCase: _case, ...rest }) => rest),
        };
        report.summary = summarizeCases(suiteName, report.cases);
        const byStrategy = summarizeByFacet(suiteName, report.cases, "strategy");
        if (byStrategy) report.byStrategy = byStrategy;
        const agreement = agreementFor(suiteName, report.cases);
        if (agreement.length) report.agreement = agreement;
        const usageAfter = await app?.usage();
        if (usageBefore && usageAfter) {
          const unpriced = usageAfter.unpriced - usageBefore.unpriced;
          report.usage = {
            calls: usageAfter.calls - usageBefore.calls,
            inputTokens: usageAfter.inputTokens - usageBefore.inputTokens,
            outputTokens: usageAfter.outputTokens - usageBefore.outputTokens,
            unpriced,
            // Not Organic aliases carry no local price; the wallet is the ledger.
            costMicrousd: unpriced ? null : usageAfter.costMicrousd - usageBefore.costMicrousd,
          };
        }
        if (app && options.model === "notorganic") {
          // Settlement lags the response slightly; give the ledger a moment.
          await sleep(3_000);
          const billed = await app.billed(suiteStarted, Date.now());
          report.billed = billed
            ? {
                microusd: billed.billedMicrousd,
                settled: billed.settledRequests,
                unresolved: billed.unresolvedRequests,
              }
            : null;
        }

        if (options.arize && arizeSpace) {
          const examples = cases.map((c) => suite.example(c) as Record<string, string | number | boolean> & { case_id: string });
          const dataset = await ensureDataset(
            { space: arizeSpace },
            `twyne-app-${suiteName}-${corpusHash(examples)}`,
            examples,
          );
          const experimentRuns: ExperimentRun[] = report.cases.flatMap((c) => {
            const exampleId = dataset.examples.get(c.case_id);
            if (!exampleId || c.skipped) return [];
            return [
              {
                example_id: exampleId,
                output: c.output,
                ok: c.ok,
                error: c.error,
                scores: c.scores,
                metadata: {
                  case_id: c.case_id,
                  target: report.target,
                  app_model: report.model,
                  driver: report.driver,
                  judge: report.judge,
                  latency_ms: c.latencyMs,
                  trace_id: c.traceId,
                },
              },
            ];
          });
          const created = await uploadExperiment(dataset.id, experiment, experimentRuns);
          report.arize = {
            dataset: dataset.name,
            datasetId: dataset.id,
            experimentId: created.id,
          };
          log(`  ↑ Arize: experiment "${experiment}" on dataset ${dataset.name}`);
          if (created.labelOnly.length)
            log(`    uploaded as labels (not every case applies): ${created.labelOnly.join(", ")}`);
        }

        printReport(report, log);
        reports.push(report);
        suiteReports.push(report);
        await writeReport(report);
      }

      // Across rounds and against the baseline, on the last round's report.
      const last = suiteReports[suiteReports.length - 1];
      let amended = false;
      if (suiteReports.length > 1) {
        last.repeatability = repeatability(suiteReports.map((r) => r.cases));
        for (const line of formatRepeatability(last.repeatability)) log(line);
        amended = true;
      }
      const before = baseline?.get(suiteName);
      if (before?.length) {
        last.comparison = comparePaired(
          suiteName,
          averageRuns(before),
          averageRuns(suiteReports as ReportLike[]),
          { base: describe(before), next: describe(suiteReports as ReportLike[]) },
        );
        for (const line of formatComparison(last.comparison)) log(line);
        amended = true;
      } else if (baseline) log(`  (no baseline report for ${suiteName})`);
      if (amended) await writeReport(last);
    }
  } finally {
    await flushArize();
    await app?.close();
  }
  return reports;
}

async function main(): Promise<void> {
  const { values } = parseArgs({
    options: {
      suite: { type: "string", default: "all" },
      target: { type: "string", default: "local" },
      model: { type: "string", default: "mock" },
      "system-one": { type: "string" },
      research: { type: "string" },
      driver: { type: "string", default: "mcp" },
      judge: { type: "string", default: "none" },
      jev: { type: "boolean", default: false },
      case: { type: "string" },
      limit: { type: "string" },
      concurrency: { type: "string", default: "2" },
      repeat: { type: "string", default: "1" },
      baseline: { type: "string" },
      arize: { type: "boolean", default: false },
      "arize-space": { type: "string" },
      trace: { type: "boolean", default: false },
      project: { type: "string", default: "twyne-app-evals" },
      experiment: { type: "string" },
      out: { type: "string" },
      strict: { type: "boolean", default: false },
      help: { type: "boolean", short: "h", default: false },
    },
  });
  if (values.help) {
    console.log(HELP);
    return;
  }
  const suites = (values.suite === "all" ? Object.keys(SUITES) : values.suite.split(","))
    .map((s) => s.trim())
    .filter(Boolean) as SuiteName[];
  for (const suite of suites)
    if (!(suite in SUITES)) throw new Error(`Unknown suite: ${suite}`);
  const choice = <T extends string>(value: string, allowed: readonly T[], flag: string): T => {
    if (!allowed.includes(value as T))
      throw new Error(`--${flag} must be one of ${allowed.join(", ")}`);
    return value as T;
  };
  const repeat = Number(values.repeat);
  if (!Number.isInteger(repeat) || repeat < 1) throw new Error("--repeat must be a positive integer");
  const reports = await runAppEvals({
    suites,
    target: choice(values.target, ["local", "live"], "target"),
    model: choice(values.model, ["mock", "openai-compatible", "notorganic"], "model"),
    systemOne: values["system-one"]
      ? choice<SystemOneMode>(values["system-one"], ["mock", "direct", "off"], "system-one")
      : undefined,
    research: values.research
      ? choice<ResearchMode>(values.research, ["mock", "notorganic", "keenable", "custom", "off"], "research")
      : undefined,
    driver: choice(values.driver, ["mcp", "mcp-stdio"], "driver"),
    judge: choice(values.judge, ["none", "notorganic", "openai-compatible"], "judge"),
    jev: values.jev,
    caseIds: values.case?.split(",").map((s) => s.trim()).filter(Boolean),
    limit: values.limit ? Number(values.limit) : undefined,
    concurrency: Number(values.concurrency),
    repeat,
    baseline: values.baseline?.split(",").map((s) => s.trim()).filter(Boolean),
    arize: values.arize,
    arizeSpace: values["arize-space"],
    trace: values.trace,
    project: values.project,
    experiment: values.experiment,
    out:
      values.out ??
      join(fileURLToPath(new URL("../../reports/app-evals", import.meta.url))),
    env: { ...process.env },
  });
  const errors = reports.reduce((sum, r) => sum + r.errors, 0);
  if (values.strict && errors > 0) process.exitCode = 1;
}

if (import.meta.main) {
  main().catch((error) => {
    console.error(`[twyne:app-evals] ${error instanceof Error ? error.message : String(error)}`);
    process.exit(1);
  });
}

