): Promise<Record<string, Score>> {
  const answers = await askJev(
    jev,
    jevRubricState(testCase.draftText, testCase.brief.answers),
    JEV_RUBRIC_QUESTIONS,
  );
  const scores: Record<string, Score> = {};
